package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen1Test {





    @Test
    public void testComputeCheckSum_SingleNegativeByte() {
        // In Java, byte is signed. -1 is 0xFF. 
        // BYTE_MASK (0xFF) & -1 (0xFF) = 255
        byte[] buf = new byte[]{(byte) 0xFF};
        long expected = 255L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum of single byte 0xFF should be 255", expected, actual);
    }








}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen1Test {







    @Test
    public void testComputeCheckSum_MultipleBytes() {
        // 0x01 + 0x02 + 0xFF = 1 + 2 + 255 = 258
        byte[] buf = new byte[]{0x01, 0x02, (byte) 0xFF};
        long expected = 258L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum calculation for multiple bytes failed", expected, actual);
    }






}

