package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen1Test {











    @Test
    public void testComputeCheckSum_LargeValue() {
        // Testing that the sum accumulates correctly into a long
        // 255 * 10 = 2550
        byte[] buf = new byte[10];
        for (int i = 0; i < 10; i++) {
            buf[i] = (byte) 0xFF;
        }
        long expected = 2550L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum calculation for large values failed", expected, actual);
    }


}

